python3 -c "
import subprocess, re

# Get all function symbols (T/t/W/w) from dynamic symbol table
result = subprocess.run(['nm', '-D', '--defined-only', 'libmonosgen-2.0.so'], capture_output=True, text=True)
syms = []
for line in result.stdout.strip().split('\n'):
    parts = line.strip().split()
    if len(parts) >= 3 and parts[1] in ('T', 't', 'W', 'w'):
        syms.append((int(parts[0], 16), parts[2]))

# Also try readelf for more complete symbol info
result2 = subprocess.run(['readelf', '-s', 'libmonosgen-2.0.so'], capture_output=True, text=True)
for line in result2.stdout.strip().split('\n'):
    m = re.match(r'\s+\d+:\s+([0-9a-f]+)\s+(\d+)\s+FUNC\s+\w+\s+\w+\s+\d+\s+(.+)', line)
    if m:
        addr = int(m.group(1), 16)
        size = int(m.group(2))
        name = m.group(3).strip()
        if addr > 0 and (addr, name) not in syms:
            syms.append((addr, name))

syms.sort()
print(f'Total function symbols: {len(syms)}')

targets = {
    '#01': 0x222098,
    '#02': 0x222234,
    '#03': 0x19bac0,
    '#06': 0x19bc14,
}

for frame, pc in sorted(targets.items()):
    # Binary search for nearest symbol
    best = None
    for addr, name in syms:
        if addr <= pc:
            best = (addr, name)
        else:
            break
    if best:
        offset = pc - best[0]
        # Also find the next symbol to gauge function size
        next_sym = None
        for addr, name in syms:
            if addr > best[0]:
                next_sym = (addr, name)
                break
        gap = next_sym[0] - best[0] if next_sym else 0
        print(f'  {frame} pc {hex(pc)}: {best[1]}+0x{offset:x} (func at {hex(best[0])}, next sym at +{hex(gap)})')
    else:
        print(f'  {frame} pc {hex(pc)}: ??')
"

